// Kane *_test.md generator and approved-test hash.
//
// Generated files live in .greenlight/tests/<test-id>_test.md. Output is fully
// determined by the normalised spec and GENERATOR_VERSION, so the same spec
// always produces byte-identical files.
//
// Approved-test hash = SHA-256 of canonical JSON of:
//   { format, generator, spec (normalised), files: [{file, sha256}] }
// Comments and formatting in greenlight.yaml do not affect it; any change to a
// project field, claim, test, step or generated file does.

import path from "node:path";
import { readFile, writeFile, mkdir, readdir } from "node:fs/promises";
import { parseSpec } from "./schema.js";
import { sha256Bytes, canonicalJson } from "../evidence/hash.js";

export const GENERATOR_VERSION = "greenlight-testgen/1";
export const BUNDLE_FORMAT = "greenlight.approved-tests/v1";
export const SPEC_FILE = "greenlight.yaml";
export const TESTS_DIR = path.join(".greenlight", "tests");

export const testFileName = (testId) => `${testId}_test.md`;

/** Kane step text for an exact visible-text assertion. */
export function expectTextStep(text) {
  return `Verify the page shows the exact text "${text}".`;
}

export function renderTest(spec, test) {
  const url = new URL(test.startPath, spec.project.url).href;
  const tags = test.claims.map((c) => c.toLowerCase());
  const claimTexts = new Map(spec.claims.map((c) => [c.id, c.text]));
  const lines = [
    "---",
    `mode: ${test.mode}`,
    `url: ${url}`,
    `tags: [${tags.join(", ")}]`,
    `max_steps: ${test.maxSteps}`,
    "---",
    "",
    `<!-- Generated by Greenlight (${GENERATOR_VERSION}) from ${SPEC_FILE}, test "${test.id}".`,
    "     Do not edit: any change to this file invalidates approval.",
    ...test.claims.map((c) => `     ${c}: ${claimTexts.get(c)}`),
    "-->",
    `# ${test.claims.join(", ")}: ${test.title}`,
    "",
  ];
  for (const s of test.steps) {
    lines.push(`## ${s.name}`);
    lines.push(s.kind === "expect_text" ? expectTextStep(s.text) : s.text);
    lines.push("");
  }
  return lines.join("\n");
}

/** Render every test. Returns [{testId, file, claims, content, sha256}] sorted by file. */
export function renderAll(spec) {
  return spec.tests
    .map((t) => {
      const content = renderTest(spec, t);
      return { testId: t.id, file: testFileName(t.id), claims: [...t.claims], content, sha256: sha256Bytes(content) };
    })
    .sort((a, b) => a.file.localeCompare(b.file));
}

/** The approved-test list in the shape Step 2's classifier takes. */
export function toApprovedTests(rendered) {
  return { tests: rendered.map((r) => ({ file: r.file, claims: [...r.claims] })) };
}

export function bundleHash(spec, rendered) {
  return sha256Bytes(
    canonicalJson({
      format: BUNDLE_FORMAT,
      generator: GENERATOR_VERSION,
      spec,
      files: rendered.map((r) => ({ file: r.file, sha256: r.sha256 })),
    }),
  );
}

/** Load and render the project's spec. Throws SpecError for an invalid spec. */
export async function loadProject(root) {
  const specPath = path.join(root, SPEC_FILE);
  const specText = await readFile(specPath, "utf8");
  const spec = parseSpec(specText);
  const rendered = renderAll(spec);
  return {
    root,
    specPath,
    testsDir: path.join(root, TESTS_DIR),
    spec,
    rendered,
    hash: bundleHash(spec, rendered),
    specFileSha256: sha256Bytes(specText),
  };
}

/** Write generated tests (only files whose content differs). Never deletes anything. */
export async function writeGenerated(root) {
  const p = await loadProject(root);
  await mkdir(p.testsDir, { recursive: true });
  const written = [];
  const unchanged = [];
  for (const r of p.rendered) {
    const full = path.join(p.testsDir, r.file);
    let current = null;
    try {
      current = await readFile(full, "utf8");
    } catch {
      /* new file */
    }
    if (current === r.content) unchanged.push(r.file);
    else {
      await writeFile(full, r.content);
      written.push(r.file);
    }
  }
  const check = await checkGenerated(p);
  return { hash: p.hash, written, unchanged, unexpected: check.unexpected, project: p };
}

/** Compare generated tests on disk with what the spec produces. */
export async function checkGenerated(project) {
  const missing = [];
  const modified = [];
  for (const r of project.rendered) {
    let current;
    try {
      current = await readFile(path.join(project.testsDir, r.file), "utf8");
    } catch {
      missing.push(r.file);
      continue;
    }
    if (current !== r.content) modified.push(r.file);
  }
  let onDisk = [];
  try {
    onDisk = (await readdir(project.testsDir)).filter((f) => f.endsWith("_test.md"));
  } catch {
    /* no directory yet */
  }
  const expected = new Set(project.rendered.map((r) => r.file));
  const unexpected = onDisk.filter((f) => !expected.has(f)).sort();
  return { clean: missing.length === 0 && modified.length === 0 && unexpected.length === 0, missing, modified, unexpected };
}
